using System.Globalization;
using System.Text;
using fire.Bytecode;
using fire.Runtime;
using fire.Values;
using fire.Ast;

namespace fire.Native
{
    /// <summary>
    /// Modules (ROADMAP 9, docs/NATIVE_BACKEND.md "Getrennte Übersetzung"): the prelude (`core`), each import and each library of the project is a module whose C does
    /// not depend on the program that uses it, so that it can be built once and linked into many programs (linkage "static").
    ///
    /// A library module is generated by a generator of its own that sees only the classes of the module and of the modules it needs (a view of the program,
    /// <see cref="LibraryView"/>). It keeps the public and protected members of its classes (its API is the root of what it keeps; private ones when reached), names its
    /// classes by a base that the program fixes (`fire_mb_M + k`), calls the members of other modules by stable exported names (`fx_M_Class__Member_i`) and serves
    /// its own classes itself (CppGenerator.ModuleDispatch.cs: dispatchers, field helpers, `is of`, operators, ... over its classes; the others through the tables of
    /// the runtime). The program is the one module that knows every class (a closed world): it calls members of libraries directly where the types allow, and writes
    /// the class descriptors and the tables of the runtime. Every helper takes the scope list and the caller (<see cref="Modular"/>, one signature for all; the
    /// rows of the tables call them). What a library needs from the program is its <see cref="ModuleNeeds"/>. Numbers the program decides at link time - the units,
    /// the enums, the catch types, the sources for the debugger - a library uses through tables the program defines (`fire_units_M[k]`, ...).
    /// </summary>
    public sealed partial class CppGenerator
    {
        private enum ModuleRole { Single, Library, Program }

        /// <summary>A library module of the program: its name (`core`, the import key, the import name of a library of the project), the C name, its sources
        /// and the classes it declares (in a fixed order: their names - the program and the module number them alike).</summary>
        internal sealed class ModuleSpec
        {
            public required string Name;
            public required string Id;
            public required int Index;
            public readonly HashSet<int> Sources = new();
            /// <summary>The modules it needs, transitively (in dependency order).</summary>
            public readonly List<ModuleSpec> Deps = new();
            public readonly List<string> Classes = new();
            /// <summary>The program: the class id of the module's first class.</summary>
            public int Base;
        }

        /// <summary>What a library module needs from the program (it only declares these; the program generates them for every class), and the numbers it uses
        /// that the program decides (by the module's own index: units, enums, catch types, sources).</summary>
        internal sealed class ModuleNeeds
        {
            public readonly SortedSet<(string Name, int Argc)> Dispatchers = new();
            public readonly SortedSet<string> Fields = new(StringComparer.Ordinal);
            public readonly SortedSet<string> FieldAddresses = new(StringComparer.Ordinal);
            public readonly SortedSet<string> IsOf = new(StringComparer.Ordinal);
            public readonly SortedSet<(string Cls, int Index)> TArgOfs = new();
            public readonly SortedSet<string> Operators = new(StringComparer.Ordinal);
            public readonly SortedSet<string> OverloadClasses = new(StringComparer.Ordinal);
            public readonly SortedSet<string> ErrorClasses = new(StringComparer.Ordinal);
            public readonly HashSet<(string Name, int Argc)> RefCallSites = new();
            /// <summary>The static fields it declares (the program releases them at the end) and those of other modules it uses.</summary>
            public readonly SortedSet<(string Class, string Field)> StaticFields = new();
            public readonly List<Unit> Units = new();
            public readonly List<EnumType> Enums = new();
            public readonly List<string> ExcTypes = new();
            public readonly SortedSet<string> ReflectionNatives = new(StringComparer.Ordinal);
            /// <summary>The classes whose objects its code can make (of its own and of other modules): the program generates for these.</summary>
            public readonly SortedSet<string> Classes = new(StringComparer.Ordinal);
            /// <summary>Linkage "static": the natives in C it calls (the program defines `fire_cn_` functions for them).</summary>
            public readonly SortedDictionary<string, (int Argc, bool NeedsList, string Import)> SharedNatives = new(StringComparer.Ordinal);
        }

        /// <summary>A library module as generated: its C (without the head of the file: <see cref="Head"/>, the defines and the runtime), its natives in C++ (the thunks),
        /// what it needs and the switches it was generated with.</summary>
        internal sealed class ModuleOutput
        {
            public required ModuleSpec Spec;
            public required string Body;
            public required string NativeThunks;
            /// <summary>The C++ functions of the natives in C++ its thunks call.</summary>
            public IReadOnlyList<string> CppNatives = Array.Empty<string>();
            public required ModuleNeeds Needs;
            public required ModuleFlags Flags;
            /// <summary>Linkage "static": the natives in C of the module's own import (they go into its file).</summary>
            public string NativesC = "";
            /// <summary>The exported names of its members (the interface lists them).</summary>
            public IReadOnlyList<string> Exports = Array.Empty<string>();
            /// <summary>Its code calls the JSON engine: linkage "static" compiles the engine into its file (once, not with every program).</summary>
            public bool JsonEngine;
            /// <summary>Linkage "shared" on Windows: what it uses of the program (name -> the C declaration): pointers of its DLL that its `fire_link_` function fills.</summary>
            public SortedDictionary<string, string> HostImports = new(StringComparer.Ordinal);
            /// <summary>Linkage "shared" on Windows: its `fire_link_` function (the end of its file).</summary>
            public string LinkC = "";
        }

        /// <summary>The switches of the generator that hold for the whole program (they change what every module's code has to do): a module is generated with
        /// those of all modules (cache variants per set, ROADMAP 9.4).</summary>
        internal readonly record struct ModuleFlags(bool Exceptions, bool Threads, bool Actors, bool Reflection, bool Probes, bool ElementPointers, bool TryDepth,
            bool GlobalOwn, bool TakeUpwards, bool TakeEnumerate, bool Json, bool TimeObj, bool StringCall, bool Graphics, bool Windows)
        {
            public ModuleFlags Or(ModuleFlags o) => new(Exceptions || o.Exceptions, Threads || o.Threads, Actors || o.Actors, Reflection || o.Reflection, Probes || o.Probes,
                ElementPointers || o.ElementPointers, TryDepth || o.TryDepth, GlobalOwn || o.GlobalOwn, TakeUpwards || o.TakeUpwards, TakeEnumerate || o.TakeEnumerate,
                Json || o.Json, TimeObj || o.TimeObj, StringCall || o.StringCall, Graphics || o.Graphics, Windows || o.Windows);
            public override string ToString() => string.Concat(new[] { Exceptions, Threads, Actors, Reflection, Probes, ElementPointers, TryDepth, GlobalOwn, TakeUpwards, TakeEnumerate, Json, TimeObj, StringCall, Graphics, Windows }.Select(b => b ? '1' : '0'));
        }

        private ModuleRole _role = ModuleRole.Single;
        /// <summary>The module this generator makes (a library).</summary>
        private ModuleSpec? _self;
        /// <summary>The library modules (the program: all of them; a library: the modules it needs), by name.</summary>
        private Dictionary<string, ModuleSpec> _modules = new(StringComparer.Ordinal);
        private Dictionary<int, ModuleSpec> _moduleOfSource = new();
        /// <summary>The switches the modules agreed on (null: this generator decides alone).</summary>
        private ModuleFlags? _forced;
        /// <summary>The program: the library modules as generated (their needs are roots of the program).</summary>
        private List<ModuleOutput>? _libraries;
        /// <summary>The program, one file (FIRE_MODULES=1, phase A): the code of the library modules, put in after the runtime.</summary>
        private string? _moduleBodies;

        /// <summary>The program is made of modules (linkage "static", or FIRE_MODULES=1): uniform signatures of the helpers (every module serves its own classes, ROADMAP 9 B2).</summary>
        private bool Modular => _role != ModuleRole.Single;
        private bool LibraryRole => _role == ModuleRole.Library;
        /// <summary>The prefix of the names a library module keeps to itself (its functions, constants and tables): `core_` - so that several modules fit into one file.</summary>
        private string Px => _self is { } m ? m.Id + "_" : "";
        /// <summary>`static `: every module has its own helpers.</summary>
        private string HelperStorage => "static ";

        /// <summary>The module of a class (null: the program).</summary>
        private ModuleSpec? ModuleOf(RuntimeClass rc) =>
            rc.Decl != null && _moduleOfSource.TryGetValue(rc.Decl.Source, out var m) ? m : null;

        /// <summary>Does this generator make the code of the class?</summary>
        private bool IsOwnClass(RuntimeClass rc) => _role switch
        {
            ModuleRole.Library => ReferenceEquals(ModuleOf(rc), _self),
            ModuleRole.Program => ModuleOf(rc) == null,
            _ => true,
        };

        // ---- the members of classes by a name that every module computes alike ----------------------------------------------
        private Dictionary<FunctionProto, (ModuleSpec? Module, string Key)>? _protoKeys;

        /// <summary>The module and the stable key of a member of a class (`List.Add#0`, `List.ctor1`, `List.Add#0.d1` for a default value); false for a lambda or
        /// another function that lives inside the code of its module.</summary>
        private bool ProtoKey(FunctionProto proto, out ModuleSpec? module, out string key)
        {
            if (_protoKeys == null)
            {
                _protoKeys = new Dictionary<FunctionProto, (ModuleSpec?, string)>(ReferenceEqualityComparer.Instance);
                foreach (var rc in _program.Program.Classes.Values.OrderBy(c => c.Name, StringComparer.Ordinal))
                {
                    var classModule = ModuleOf(rc);
                    void Add(FunctionProto p, string k, (ModuleSpec? Module, bool Known) parent = default)
                    {
                        // (the module of a member is that of its code: a class extension of a library - `Where` of linq on List - adds members of its own module to a class of
                        // another; a default value - often without lines of its own - belongs to its method)
                        var mod = p.Chunk.FirstSourceIndex is int src ? (_moduleOfSource.TryGetValue(src, out var m) ? m : null) : parent.Known ? parent.Module : classModule;
                        if (!_protoKeys.TryAdd(p, (mod, k))) return;
                        for (int j = 0; j < p.ParamDefaults.Count; j++) if (p.ParamDefaults[j] is { } dp) Add(dp, k + ".d" + j, (mod, true));
                    }
                    foreach (var (name, protos) in rc.Methods.OrderBy(m => m.Key, StringComparer.Ordinal))
                        for (int i = 0; i < protos.Count; i++) Add(protos[i], $"{rc.Name}.{name}#{i}");
                    foreach (var (argc, p) in rc.Constructors.OrderBy(c => c.Key)) Add(p, $"{rc.Name}.ctor{argc}");
                    for (int i = 0; i < rc.ExtraConstructors.Count; i++) Add(rc.ExtraConstructors[i], $"{rc.Name}.xctor{i}");
                    if (rc.Destructor != null) Add(rc.Destructor, $"{rc.Name}.dtor");
                }
            }
            if (_protoKeys.TryGetValue(proto, out var found)) { module = found.Module; key = found.Key; return true; }
            module = null; key = "";
            return false;
        }

        /// <summary>The exported C name of a member of a class of a library module.</summary>
        private static string ExportName(ModuleSpec module, string key) =>
            $"fx_{module.Id}_{Mangle(key.Replace(".", "__").Replace("#", "_"))}";

        /// <summary>The C expression of a class id: a number, or in a library the module's base plus the class's place in its module.</summary>
        private string ClassIdExpr(ClassInfo cls) => cls.IdText ?? cls.Id.ToString(CultureInfo.InvariantCulture);

        /// <summary>A library: the base of its own classes (`fire_mb_M`, set by the program).</summary>
        private string ModuleBase(ModuleSpec m) => $"fire_mb_{m.Id}";

        /// <summary>A class of another module, as a library sees it: not in this generator's list (no switch knows it), its id the other module's base plus its place there.</summary>
        private ClassInfo? ForeignClass(string name, RuntimeClass rc)
        {
            if (!LibraryRole || IsOwnClass(rc)) return null;
            if (_foreignClasses.TryGetValue(name, out var known)) return known;
            var mod = ModuleOf(rc) ?? throw new NativeNotSupportedException($"the library module '{_self!.Name}' uses the class '{name}' of the program");
            int k = mod.Classes.IndexOf(rc.Name);
            if (k < 0) throw new NativeNotSupportedException($"the class '{name}' is not part of its module '{mod.Name}'");
            var info = new ClassInfo { Rc = rc, Id = -1, IdText = $"({ModuleBase(mod)} + {k}u)" };
            _foreignClasses[name] = info;
            _usedModules.Add(mod);
            return info;
        }
        private readonly Dictionary<string, ClassInfo> _foreignClasses = new(StringComparer.Ordinal);
        /// <summary>The other modules whose classes a library uses (it declares their bases).</summary>
        private readonly HashSet<ModuleSpec> _usedModules = new();

        // ---- numbers the program decides: a library uses them through tables of the program -------------------------------------------
        /// <summary>The C of a unit id in code (a library: through the table of the program).</summary>
        private string UnitC(int unit) => LibraryRole && unit != 0 ? $"fire_units_{_self!.Id}[{unit}]" : unit.ToString(CultureInfo.InvariantCulture);
        /// <summary>The C of an enum number in code.</summary>
        private string EnumC(int index) => LibraryRole && index != 0 ? $"fire_enums_{_self!.Id}[{index}]" : index.ToString(CultureInfo.InvariantCulture);
        /// <summary>The C of a source index for the debugger.</summary>
        private string DbgSrc(int src) => LibraryRole && _self!.Sources.Contains(src) ? $"fire_dbgsrc_{_self.Id}[{DebugSourceIndex(src)}]" : src.ToString(CultureInfo.InvariantCulture);   // (another source: line 0, an instruction before the first line of the function)
        /// <summary>A source of a library by its place among the module's sources (the same in every program that uses the module).</summary>
        private int DebugSourceIndex(int src)
        {
            int at = _self!.Sources.OrderBy(s => s).ToList().IndexOf(src);
            if (at < 0) throw new NativeNotSupportedException($"the library module '{_self.Name}' has code of another module's source {src}");
            return at;
        }

        /// <summary>The switches of this generator, as the modules exchange them.</summary>
        private ModuleFlags CurrentFlags => new(_usesExceptions, _usesThreads, _usesActors, _usesReflection, _usesProbes, _usesElementPointers, _usesTryDepth,
            _usesGlobalOwn, _usesTakeUpwards, _usesTakeEnumerate, _usesJson, _needsTimeObj, _usesStringCall, _usesGraphics, _usesWindows);

        /// <summary>Starts with the switches the modules agreed on.</summary>
        private void ApplyForcedFlags()
        {
            if (_forced is not { } f) return;
            if (f.Threads) UseThreads();
            if (f.Exceptions) UseExceptions();
            if (f.Windows) UseWindows();
            if (f.Graphics) UseGraphics();
            _usesActors |= f.Actors;
            if (f.Reflection) UseReflection();
            _usesProbes |= f.Probes;
            _usesElementPointers |= f.ElementPointers;
            _usesTryDepth |= f.TryDepth;
            _usesGlobalOwn |= f.GlobalOwn;
            _usesTakeUpwards |= f.TakeUpwards;
            _usesTakeEnumerate |= f.TakeEnumerate;
            if (f.Json) UseJson();
            _needsTimeObj |= f.TimeObj;
            _usesStringCall |= f.StringCall;
        }

        /// <summary>FIRE_MODULES=1 (tests, phase A of ROADMAP 9): every native build is made of modules, in one file.</summary>
        public static bool ModulesFromEnvironment => Environment.GetEnvironmentVariable("FIRE_MODULES") == "1";

        // ---- the modules of a program ----------------------------------------------------------------------------------------------------
        /// <summary>The library modules of the program in dependency order (`core` first), with their sources, classes and needs.</summary>
        internal static List<ModuleSpec> ModulesOf(LinkedProgram program)
        {
            var result = new List<ModuleSpec>();
            var modules = program.SourceModules ?? throw new NativeNotSupportedException("the program does not carry the modules of its sources (link it with Linker.CompileAndLink)");
            var byName = new Dictionary<string, ModuleSpec>(StringComparer.Ordinal);
            var names = modules.Where(m => m != null).Select(m => m!).Distinct().ToList();
            var deps = program.ModuleDeps ?? new Dictionary<string, IReadOnlyList<string>>();
            // dependency order: a module after the ones it needs (`core` before all)
            var ordered = new List<string>();
            var visiting = new HashSet<string>(StringComparer.Ordinal);
            void Visit(string name)
            {
                if (ordered.Contains(name) || !visiting.Add(name)) return;
                if (name != "core") Visit("core");
                foreach (var d in deps.GetValueOrDefault(name) ?? Array.Empty<string>()) if (names.Contains(d)) Visit(d);
                ordered.Add(name);
            }
            foreach (var n in names) Visit(n);
            var ids = new HashSet<string>(StringComparer.Ordinal);
            foreach (var name in ordered)
            {
                string id = ModuleCName(name);
                for (int k = 2; !ids.Add(id); k++) id = ModuleCName(name) + k.ToString(CultureInfo.InvariantCulture);
                var spec = new ModuleSpec { Name = name, Id = id, Index = result.Count };
                for (int i = 0; i < modules.Count; i++) if (modules[i] == name) spec.Sources.Add(i);
                result.Add(spec);
                byName[name] = spec;
            }
            foreach (var spec in result)
            {
                var seen = new HashSet<string>(StringComparer.Ordinal);
                void Close(string name)
                {
                    if (!seen.Add(name)) return;
                    if (name != "core") Close("core");
                    foreach (var d in deps.GetValueOrDefault(name) ?? Array.Empty<string>()) if (byName.ContainsKey(d)) Close(d);
                }
                Close(spec.Name);
                seen.Remove(spec.Name);
                spec.Deps.AddRange(result.Where(m => seen.Contains(m.Name)));
            }
            var sourceModule = new Dictionary<int, ModuleSpec>();
            foreach (var spec in result) foreach (int s in spec.Sources) sourceModule[s] = spec;
            foreach (var rc in program.Program.Classes.Values)
                if (rc.Decl != null && sourceModule.TryGetValue(rc.Decl.Source, out var owner)) owner.Classes.Add(rc.Name);
            foreach (var spec in result) spec.Classes.Sort(StringComparer.Ordinal);
            return result;
        }

        /// <summary>The C name of a module: `core`, `ui`, `pkg_name` - letters, digits and `_`.</summary>
        private static string ModuleCName(string name)
        {
            string plain = name.StartsWith(fire.Package.Manager.PackageStore.KeyPrefix, StringComparison.Ordinal) ? name.Substring(fire.Package.Manager.PackageStore.KeyPrefix.Length) : name;
            var sb = new StringBuilder("m");
            foreach (char c in plain) sb.Append(char.IsAsciiLetterOrDigit(c) ? c : '_');
            return sb.ToString();
        }

        /// <summary>The program as a library module sees it: its own classes and those of the modules it needs, no top level (a library has none).</summary>
        internal static LinkedProgram LibraryView(LinkedProgram program, ModuleSpec module)
        {
            var visible = new HashSet<string>(module.Classes, StringComparer.Ordinal);
            foreach (var dep in module.Deps) visible.UnionWith(dep.Classes);
            var classes = program.Program.Classes.Where(kv => visible.Contains(kv.Value.Name)).ToDictionary(kv => kv.Key, kv => kv.Value);
            var compiled = new CompiledProgram { TopLevel = new Chunk(), Classes = classes, ExternSignatures = program.Program.ExternSignatures, Resources = program.Program.Resources, CustomUnits = new() };
            return new LinkedProgram(compiled, program.NativeImports, program.FirstUserSource, program.ExecutionMode)
            {
                NativeNames = program.NativeNames, FloatWidth = program.FloatWidth, IntWidth = program.IntWidth, PackageNatives = program.PackageNatives, PackageNativeLibraries = program.PackageNativeLibraries,
                SourceFiles = program.SourceFiles, SourceHashes = program.SourceHashes, SourceModules = program.SourceModules, ModuleDeps = program.ModuleDeps, SourceTextHashes = program.SourceTextHashes,
            };
        }

        /// <summary>The program built from modules, in one file (phase A of ROADMAP 9: the same code as separate libraries, only not compiled apart): the library
        /// modules in dependency order, then the program, which defines what they declare. The switches every module is generated with are those of all of them.</summary>
        public static NativeSources GenerateModular(LinkedProgram program, TargetProfile? target = null, Func<int>? chooseSdl = null, StrippingLevel? stripping = null)
        {
            target ??= TargetProfile.Host;
            var specs = ModulesOf(program);
            ModuleFlags? flags = null;
            for (int round = 0; ; round++)
            {
                var outputs = new List<ModuleOutput>();
                var union = flags ?? default;
                foreach (var spec in specs)
                {
                    var output = GenerateLibrary(program, spec, specs, target, stripping, flags);
                    outputs.Add(output);
                    union = union.Or(output.Flags);
                }
                var main = new CppGenerator(program, target)
                {
                    _chooseSdl = chooseSdl, _strip = EffectiveStripping(program, stripping), _role = ModuleRole.Program, _forced = flags, _libraries = outputs,
                    _moduleBodies = string.Concat(outputs.Select(o => o.Body)),
                };
                main.SetModules(specs, null);
                string c = main.Run();
                union = union.Or(main.CurrentFlags);
                if (flags is { } known && known.Equals(union)) return new NativeSources(c, main._nativesCode);
                if (round > 4) throw new NativeNotSupportedException("the modules do not agree on the switches of the program");
                flags = union;
            }
        }

        /// <summary>Generates one library module (its view of the program, its own classes kept).</summary>
        internal static ModuleOutput GenerateLibrary(LinkedProgram program, ModuleSpec spec, IReadOnlyList<ModuleSpec> all, TargetProfile target, StrippingLevel? stripping, ModuleFlags? flags, bool separate = false,
            bool dll = false, List<(string Module, string Abi)>? plugin = null)
        {
            var view = LibraryView(program, spec);
            // (a plugin: the units it and its libraries declare are those a text in it may name - a library leaves that to the program)
            if (plugin != null) view.Program.CustomUnits = program.Program.CustomUnits;
            var generator = new CppGenerator(view, target) { _strip = LibraryStripping(program, stripping), _role = ModuleRole.Library, _forced = flags, _self = spec, _separate = separate, _dll = dll };
            // (a plugin: the tables a program defines for a library are its own; every member of its classes and of their bases is in their tables)
            if (plugin != null) { generator._plugin = true; generator._pluginDeps = plugin; generator._tablesAll = true; }
            string body;
            try
            {
                generator.SetModules(all, spec);
                body = generator.Run();
            }
            catch (NativeNotSupportedException ex) when (!ex.Message.StartsWith("module '", StringComparison.Ordinal))
            {
                if (Environment.GetEnvironmentVariable("FIRE_MODULES_TRACE") == "1") Console.Error.WriteLine($"in {(generator._cur?.Proto is { } cp ? generator.Describe(cp) : "?")} (source {generator._cur?.Chunk.FirstSourceIndex}): {ex}");
                throw new NativeNotSupportedException($"module '{spec.Name}': {ex.Message}");
            }
            string nativesC = separate ? generator.LibraryNativesC() : "";
            return new ModuleOutput
            {
                Spec = spec, Body = body, NativeThunks = generator._libraryThunks ?? "", CppNatives = generator._nativeThunks.Keys.ToList(), Needs = generator.CollectNeeds(), Flags = generator.CurrentFlags,
                NativesC = nativesC, JsonEngine = generator._callsJsonEngine, Exports = generator._funcs.Where(f => f.Export != null && !f.External).Select(f => f.Export!).Distinct().ToList(),
                HostImports = new SortedDictionary<string, string>(generator._hostImports, StringComparer.Ordinal), LinkC = dll ? generator.LibraryLinkC() : "",
            };
        }

        /// <summary>The level a library is built with: 0 keeps everything, every other level is 1 - a library keeps its API (its public and protected members, the
        /// constructors of all its classes) and what that reaches, whatever the program uses of it (it is built once for every program, ROADMAP 9 with §11).</summary>
        internal static StrippingLevel LibraryStripping(LinkedProgram program, StrippingLevel? stripping) =>
            EffectiveStripping(program, stripping) == StrippingLevel.None ? StrippingLevel.None : StrippingLevel.Protected;

        /// <summary>The modules this generator knows: a library its own and those it needs, the program all.</summary>
        private void SetModules(IReadOnlyList<ModuleSpec> all, ModuleSpec? self)
        {
            var known = self == null ? all.ToList() : self.Deps.Append(self).ToList();
            _modules = known.ToDictionary(m => m.Name, StringComparer.Ordinal);
            _moduleOfSource = new Dictionary<int, ModuleSpec>();
            foreach (var m in all) foreach (int s in m.Sources) _moduleOfSource[s] = m;
            if (self != null)
            {
                // a library numbers its classes itself, all of them, in the order of the module
                foreach (var name in self.Classes) RegisterClass(name);
            }
            else
            {
                // the program: the classes of the libraries have the first ids, each module's from its base on; a class is only generated for (dispatchers, tables) when
                // a module or the program makes objects of it - the others keep their id and stay out, like a class that is not reached (docs/NATIVE_BACKEND.md, §11)
                int next = 0;
                _fixedIds = new Dictionary<string, int>(StringComparer.Ordinal);
                foreach (var m in all)
                {
                    m.Base = next;
                    foreach (var name in m.Classes) _fixedIds[name] = next++;
                }
                _nextClassId = next;
                _progBase = next;
                foreach (var name in _libraries?.SelectMany(l => l.Needs.Classes) ?? Enumerable.Empty<string>()) if (_fixedIds.ContainsKey(name)) RegisterClass(name);
                // (a program that loads plugins: a plugin may make objects of any class of the libraries - each gets its full descriptor - and call any member of the
                // program's classes by name)
                if (_openWorld)
                {
                    foreach (var m in all) foreach (var name in m.Classes) RegisterClass(name);
                    _tablesAll = true;
                }
            }
        }

        /// <summary>What this library needs from the program.</summary>
        private ModuleNeeds CollectNeeds()
        {
            var needs = new ModuleNeeds();
            needs.Dispatchers.UnionWith(_dispatchers);
            needs.Fields.UnionWith(_fieldNames);
            needs.FieldAddresses.UnionWith(_fieldAddressTaken);
            needs.IsOf.UnionWith(_isOfTypes);
            needs.TArgOfs.UnionWith(_targOfs);
            needs.Operators.UnionWith(_operators);
            needs.OverloadClasses.UnionWith(_ovClassNames);
            needs.ErrorClasses.UnionWith(_errorClasses);
            needs.RefCallSites.UnionWith(_refCallSites);
            needs.StaticFields.UnionWith(_staticFields.Keys);
            needs.Units.AddRange(_units);
            needs.Enums.AddRange(_enumList);
            needs.ExcTypes.AddRange(_excTypes);
            needs.ReflectionNatives.UnionWith(_reflNativesUsed);
            needs.Classes.UnionWith(_demandedClasses);
            foreach (var (f, sig) in _sharedNatives) needs.SharedNatives[f] = sig;
            return needs;
        }

        /// <summary>The program: what the libraries need becomes part of what it generates (before its fixpoint).</summary>
        private void AddLibraryNeeds()
        {
            if (_libraries == null) return;
            foreach (var lib in _libraries)
            {
                var n = lib.Needs;
                // (what a library calls by name: the tables of the program's classes list it - the library serves its own classes, the runtime the others)
                foreach (var d in n.Dispatchers) _libDispatchers.Add(d);
                foreach (var name in n.Fields) _libFields.Add(name);
                foreach (var name in n.FieldAddresses) _libFieldAddresses.Add(name);
                foreach (var op in n.Operators) _libDispatchers.Add((op, 1));
                foreach (var name in n.ErrorClasses) if (!_errorClasses.Contains(name)) _errorClasses.Add(name);
                foreach (var r in n.RefCallSites) _refCallSites.Add(r);
                foreach (var (cls, field) in n.StaticFields) StaticFieldVar(cls, field);
                foreach (var u in n.Units) UnitId(u);
                foreach (var e in n.Enums) EnumIndex(e);
                foreach (var t in n.ExcTypes) ExcTypeId(t);
                foreach (var native in n.ReflectionNatives)
                {
                    UseReflection();
                    UseReflectionLevel(native);
                    if (native is "__refl_probe" or "__refl_silence" or "__refl_silence_handle") UseProbes();
                }
            }
        }

        /// <summary>The program: the bases of the library modules and the tables of the numbers they use (`fire_units_M[k]` is the program's unit for the module's unit k, ...).</summary>
        private string ModuleTables()
        {
            if (_libraries == null) return "";
            var sb = new StringBuilder();
            sb.AppendLine("/* ---- the library modules (ROADMAP 9): the bases of their classes and the numbers of the program for theirs ---- */");
            foreach (var lib in _libraries)
            {
                string id = lib.Spec.Id;
                var n = lib.Needs;
                sb.AppendLine($"const uint32_t fire_mb_{id} = {lib.Spec.Base}u;   /* {lib.Spec.Name}: {lib.Spec.Classes.Count} classes */");
                sb.AppendLine($"const uint16_t fire_units_{id}[] = {{{string.Join(", ", n.Units.Select(u => UnitId(u).ToString(CultureInfo.InvariantCulture)).DefaultIfEmpty("0"))}}};");
                sb.AppendLine($"const uint8_t fire_enums_{id}[] = {{0{string.Concat(n.Enums.Select(e => ", " + EnumIndex(e).ToString(CultureInfo.InvariantCulture)))}}};");
                sb.AppendLine($"const int32_t fire_exct_{id}[] = {{{string.Join(", ", n.ExcTypes.Select(t => ExcTypeId(t).ToString(CultureInfo.InvariantCulture)).DefaultIfEmpty("0"))}}};");
                sb.AppendLine($"const int32_t fire_dbgsrc_{id}[] = {{{string.Join(", ", lib.Spec.Sources.OrderBy(s => s).Select(s => s.ToString(CultureInfo.InvariantCulture)).DefaultIfEmpty("0"))}}};");
            }
            return sb.ToString();
        }

        /// <summary>The prototypes of the functions (those of other modules are declared, not static), the callbacks of `catch threads`, the functions proper behind the
        /// wrappers, the thunks of the lambdas and their default values.</summary>
        private void FunctionPrototypes(StringBuilder sb)
        {
            foreach (var f in _funcs) sb.AppendLine(f.Signature + ";");
            foreach (var (callback, body) in _catchCallbacks) sb.AppendLine($"static Value {callback}(Value e) {{ {body} }}");
            if (Wrapped)   // (the functions proper behind the wrappers that count the call depth: the trampolines call them directly)
                foreach (var f in _funcs.Where(f => f.Kind != FuncKind.Main && !f.External)) sb.AppendLine(f.SignatureOf(f.Name + "_b", "") + ";");
            foreach (var f in _funcs.Where(f => f.Kind == FuncKind.Lambda))
                sb.AppendLine(f.ThunkSignature + " { " + (f.ParamCount == 0 ? "(void)a; " : "") + $"return {f.Name}(lam{string.Concat(Enumerable.Range(0, f.ParamCount).Select(i => $", a[{i}]"))}); }}");
            foreach (var f in _lambdaDefaults)
            {
                sb.AppendLine($"static Value {f.Name}_d(Value lam, uint32_t i) {{");
                sb.AppendLine("    switch (i) {");
                for (int i = 0; i < f.Proto!.ParamDefaults.Count; i++)
                    if (f.Proto.ParamDefaults[i] is { } dp) sb.AppendLine($"        case {i}: return {_funcByProto[dp].Name}(lamOn(lam));");
                sb.AppendLine("        default: return Undef();");
                sb.AppendLine("    }");
                sb.AppendLine("}");
            }
        }

        /// <summary>A library: what it declares of the program (the bases and tables of the modules, the helpers it calls, the static fields of other modules).</summary>
        private string LibraryDeclarations()
        {
            var sb = new StringBuilder();
            string id = _self!.Id;
            sb.AppendLine($"/* ---- module {_self.Name} (ROADMAP 9): what the program defines for it ---- */");
            sb.Append(HostDecl($"fire_mb_{id}", $"extern const uint32_t fire_mb_{id};"));
            foreach (var m in _usedModules.OrderBy(m => m.Index)) sb.Append(HostDecl($"fire_mb_{m.Id}", $"extern const uint32_t fire_mb_{m.Id};"));
            // (as many entries as the program writes for it - see ModuleTables)
            sb.Append(HostArray($"fire_units_{id}", "uint16_t", Math.Max(1, _units.Count)));
            sb.Append(HostArray($"fire_enums_{id}", "uint8_t", _enumList.Count + 1));
            sb.Append(HostArray($"fire_exct_{id}", "int32_t", Math.Max(1, _excTypes.Count)));
            sb.Append(HostArray($"fire_dbgsrc_{id}", "int32_t", Math.Max(1, _self.Sources.Count)));
            return sb.ToString();
        }


        /// <summary>A library keeps the members of its own classes that other modules can use - public and protected (its API; ROADMAP 9 with §11: the roots of a library
        /// that is built on its own); a private member stays when its own code reaches it.</summary>
        private void KeepOwnModule()
        {
            _keeping = true;
            try { KeepOwnMembers(); RegisterPluginTargets(); }
            finally { _keeping = false; }
        }

        /// <summary>The program with library modules: the fixed ids of the classes of the libraries (null: ids by demand); the next id for a class of its own.</summary>
        private Dictionary<string, int>? _fixedIds;
        private int _nextClassId;
        /// <summary>A library: the classes its code makes objects of (registered while generating, not by keeping its members).</summary>
        private readonly SortedSet<string> _demandedClasses = new(StringComparer.Ordinal);
        private bool _keeping;

        /// <summary>A private member stays all the same: everything is kept (stripping 0, debug builds), the class or the member is marked `[Keep]` (or named as a literal
        /// to reflection by the code of this generator - the program asks so about a class of a library only by `[Keep]`: the library decides by its own literals, the
        /// program's table must not name a member the library left out).</summary>
        private bool KeepsPrivate(RuntimeClass rc, string name)
        {
            if (_strip == StrippingLevel.None || rc.Keep || rc.KeptMembers is { } kept && (kept.Contains(name) || kept.Contains(PlainMemberName(name)))) return true;
            return (LibraryRole || IsOwnClass(rc)) && (_literalClasses.Contains(rc.Name) || LiteralMember(name));
        }

        private void KeepOwnMembers()
        {
            foreach (var cls in _classList.ToList())
            {
                var rc = cls.Rc;
                if (!IsOwnClass(rc)) continue;
                KeepConstructors(rc);
                foreach (var (name, protos) in rc.Methods)
                    foreach (var m in protos.Where(p => (!ProtoKey(p, out var owner, out _) || ReferenceEquals(owner, _self)) && (p.Access != AccessModifier.Private || KeepsPrivate(rc, name))))
                    {
                        GetFunc(m, m.IsStatic ? FuncKind.Static : FuncKind.Method);
                        foreach (var dp in m.ParamDefaults) if (dp != null) GetFunc(dp, FuncKind.Init);
                    }
                if (rc.Destructor != null) GetFunc(rc.Destructor, FuncKind.Dtor);
                // (its static fields live here: the program's top level sets them, every module reads them)
                foreach (var (field, info) in rc.OwnFieldInfo.OrderBy(f => f.Key, StringComparer.Ordinal))
                    if (info.IsStatic) StaticFieldVar(rc.Name, field);
            }
            // the members it adds to classes of other modules (`class extends List` of linq)
            foreach (var rc in _program.Program.Classes.Values.Where(c => !IsOwnClass(c)).OrderBy(c => c.Name, StringComparer.Ordinal))
                foreach (var (name, protos) in rc.Methods)
                    foreach (var m in protos.Where(p => ProtoKey(p, out var owner, out _) && ReferenceEquals(owner, _self) && (p.Access != AccessModifier.Private || KeepsPrivate(rc, name))))
                    {
                        GetFunc(m, m.IsStatic ? FuncKind.Static : FuncKind.Method);
                        foreach (var dp in m.ParamDefaults) if (dp != null) GetFunc(dp, FuncKind.Init);
                    }
        }

        /// <summary>The reflection functions the code of a function calls (`__refl_*`): with modules the program defines them for every module.</summary>
        private static readonly Dictionary<string, string> SharedReflectionFunctions = new(StringComparer.Ordinal)
        {
            ["rf_class_name"] = "(Value x, OwnList* list)", ["rf_class_info"] = "(Value name, OwnList* list)", ["rf_members"] = "(Value name, OwnList* list)",
            ["rf_classes"] = "(OwnList* list)", ["rf_is_sub"] = "(Value name, Value base)", ["rf_get"] = "(Value obj, Value name, OwnList* list, uint32_t caller)",
            ["rf_set"] = "(Value obj, Value name, Value value, OwnList* list, uint32_t caller)", ["rf_call"] = "(Value obj, Value name, Value args, OwnList* list, uint32_t caller)",
            ["rf_new"] = "(Value cname, Value args, OwnList* list, uint32_t caller)", ["rf_has"] = "(Value obj, Value name)", ["rf_selector_path"] = "(Value l, OwnList* list)",
            ["rf_member_kind"] = "(Value obj, Value name, OwnList* list)", ["rf_probe"] = "(Value obj, Value member, Value kind, Value handler, OwnList* list, uint32_t caller)",
            ["rf_silence"] = "(Value obj, Value member)", ["rf_silence_handle"] = "(Value handle)", ["rf_enum_name"] = "(Value v, OwnList* list)", ["rf_enum_of"] = "(Value v, Value n)",
        };
        private readonly SortedSet<string> _reflNativesUsed = new(StringComparer.Ordinal);

        /// <summary>The program with modules: the reflection functions that code calls are not static (the libraries declare them).</summary>
        private string ShareReflection(string code)
        {
            if (!Modular) return code;
            foreach (var name in SharedReflectionFunctions.Keys) code = code.Replace($"FIRE_MAYBE_UNUSED static Value {name}(", $"FIRE_MAYBE_UNUSED Value {name}(");
            return code;
        }

        /// <summary>The code of a library module (after its fixpoint): what it declares of the program, its constants, tables and functions.</summary>
        private string LibraryBody()
        {
            var sb = new StringBuilder();
            sb.Append(_plugin ? PluginDeclarations() : LibraryDeclarations());
            foreach (var native in _reflNativesUsed)
                if (SharedReflectionFunctions.TryGetValue("rf_" + native.Substring("__refl_".Length), out var ps)) sb.Append(HostDecl($"rf_{native.Substring("__refl_".Length)}", $"Value rf_{native.Substring("__refl_".Length)}{ps};"));
            // the natives in C++ it calls: thunks of its own in the file of the natives
            var thunks = new StringBuilder();
            foreach (var (function, (index, argc, needsList)) in _nativeThunks.OrderBy(t => t.Value.Index))
            {
                string ps = ThunkParams(argc, needsList);
                string args = string.Join(", ", Enumerable.Range(0, argc).Select(i => $"a{i}").Concat(needsList ? new[] { "list" } : Array.Empty<string>()));
                // (a plugin: in its own file of natives - not the program's)
                string thunkDecl = $"Value fire_nat_{Px}{index}({ps});   // {function}";
                sb.Append(_plugin ? thunkDecl + "\n" : HostDecl($"fire_nat_{Px}{index}", thunkDecl));
                thunks.AppendLine($"extern \"C\" fire::Value fire_nat_{Px}{index}({ps.Replace("Value", "fire::Value").Replace("OwnList", "fire::OwnList")}) {{ using namespace fire; return {function}({args}); }}");
            }
            _libraryThunks = thunks.ToString();
            if (_externDecls.Count > 0)
            {
                sb.AppendLine("#ifndef FIRE_SYM\n#ifdef __APPLE__\n#define FIRE_SYM(n) \"_\" n\n#else\n#define FIRE_SYM(n) n\n#endif\n#endif");
                foreach (var decl in _externDecls.Values) sb.AppendLine(decl);
            }
            if (_usesInlineC) sb.Append(InlineCFunctions());
            for (int i = 0; i < _strings.Count; i++)
            {
                string text = _strings[i];
                string data = "{" + string.Join(", ", text.Select(c => ((int)c).ToString(CultureInfo.InvariantCulture)).Append("0")) + "}";
                sb.AppendLine($"static const fire_char16 {Px}K{i}_d[] = {data};");
                sb.AppendLine($"static const Str {Px}K{i} = {{{{IMMORTAL, R_Str}}, {text.Length}, {Px}K{i}_d}};");
            }
            foreach (var key in _staticFields.Keys)
                sb.AppendLine(IsOwnClass(FindClass(key.Class)) ? $"Value {StaticFieldVar(key.Class, key.Field)} = FIRE_UNDEF_INIT; // {key.Class}.{key.Field}" : $"extern Value {StaticFieldVar(key.Class, key.Field)}; // {key.Class}.{key.Field}");
            foreach (var (from, to) in _unitFactorCaches) sb.AppendLine($"static double {Px}kUF_{from}_{to} = 0;");
            FunctionPrototypes(sb);
            foreach (var (path, name) in _selectorPaths) sb.AppendLine($"static const char* const {name}[] = {{{string.Join(", ", path.Select(CString))}}};");
            // its helpers: they serve its own classes, the others through the tables of the runtime (ROADMAP 9 B2) - and its tables
            sb.Append(ModularHelpers());
            sb.Append(LibraryReflectionRows());
            foreach (var f in _funcs) sb.AppendLine(f.Code);
            sb.Append(PluginTrailer());
            return sb.ToString();   // (the resets of `#line` are resolved in the file it ends up in)
        }

        /// <summary>A member of a library module that the target cannot translate (fire threads on wasm): a function that ends the program with the reason when it is called.</summary>
        private string UnsupportedStub(Func f, string why)
        {
            string body = string.Concat(f.ParamNames.Select(p => $"(void){p}; ")) + (f.Kind == FuncKind.FireBody ? "(void)args; " : "")
                + $"fatal({CString("not supported on this target: " + why)});" + (f.Kind == FuncKind.FireBody ? "" : " return Undef();");
            var sb = new StringBuilder();
            if (Wrapped) sb.AppendLine($"{f.SignatureOf(f.Name + "_b", "")} {{ {body} }}");
            sb.AppendLine($"{f.Signature} {{ {body} }}");
            return sb.ToString();
        }

        /// <summary>A library: its thunks of natives in C++ (`extern "C"` functions for the file of the natives).</summary>
        private string? _libraryThunks;
    }
}
